<template>
  <!-- #ifdef H5 -->
  <div class="long-projects" @keydown="activateButton">
  <!-- #endif -->
  <!-- #ifndef H5 -->
  <view class="long-projects">
  <!-- #endif -->
    <button role="button" tabindex="0" class="lp-disclosure" :disabled="!canInteract || busy" :aria-expanded="opened" @tap="toggle"><view><text class="lp-title">长期项目<text v-if="dirty"> · 未保存</text></text><text class="lp-note">一个总目标，分阶段推进，由你验收。</text></view><text aria-hidden="true">{{ opened ? '−' : '＋' }}</text></button>
    <view v-if="opened" class="lp-panel">
      <view class="lp-actions"><button role="button" tabindex="0" class="lp-secondary" :disabled="busy || !canInteract" @tap="refresh">读取项目</button><button v-if="enabled" role="button" tabindex="0" class="lp-secondary" :disabled="busy || !canInteract" @tap="startProject">新建长期项目 ＋</button></view>
      <text class="lp-note">只在你点击时读取或保存；不自动运行、轮询或继承上一阶段的资料与记忆。模型完成不等于目标达成。</text>
      <text v-if="error" role="alert" class="lp-error">{{ error }}</text><text v-if="notice" role="status" class="lp-note">{{ notice }}</text>
      <text v-if="loaded && !enabled" class="lp-note">当前服务尚未开放长期项目；现有聊天和任务不变。</text>
      <text v-if="uncertain" class="lp-error">上次保存结果未确认，请读取项目与阶段列表核对；不会自动重发。</text>
      <view v-if="enabled && projectEditor" class="lp-editor">
        <text class="lp-label">长期目标</text><textarea v-model="draft.goal" :maxlength="-1" class="lp-field" auto-height :disabled="busy || !canInteract" placeholder="例如：在几轮沟通中完成客户交付，而不是只生成一份报告" />
        <text class="lp-label">由你定义的验收标准 · 每行一条</text><textarea v-model="draft.criteria" :maxlength="-1" class="lp-field" auto-height :disabled="busy || !canInteract" placeholder="明确最终交付物、必须保留的条件，以及你怎样确认可用" />
        <button role="button" tabindex="0" class="lp-primary" :disabled="busy || !canInteract || uncertain" @tap="saveProject">保存目标与标准，不执行</button>
      </view>
      <view v-if="enabled" class="lp-list"><button v-for="item in projects" :key="item.id" role="button" tabindex="0" class="lp-row" :disabled="busy || !canInteract" @tap="openProject(item.id)"><text class="lp-title">{{ item.goal }}</text><text class="lp-note">项目 r{{ item.revision }} · {{ projectStatus(item.status) }}</text></button><text v-if="loaded && !projects.length" class="lp-note">还没有长期项目。先写一个真实目标和你的验收标准。</text><button v-if="projectCursor" role="button" tabindex="0" class="lp-secondary" :disabled="busy || !canInteract" @tap="moreProjects">读取下一页项目</button></view>
      <view v-if="project" class="lp-current">
        <text class="lp-heading">{{ project.goal }}</text><text class="lp-note">总目标的验收标准，不是资料证据：</text><text v-for="(criterion,index) in project.acceptance_criteria" :key="index" class="lp-criterion">{{ index+1 }}. {{ criterion }}</text>
        <view class="lp-actions"><button role="button" tabindex="0" class="lp-secondary" :disabled="busy || !canInteract" @tap="refreshPhases">读取阶段</button><button role="button" tabindex="0" class="lp-secondary" :disabled="busy || !canInteract" @tap="startPhase">新增阶段 ＋</button></view>
        <view v-if="phaseEditor" class="lp-editor">
          <text class="lp-label">新阶段标题</text><input v-model="phaseDraft.title" :maxlength="-1" class="lp-field" :disabled="busy || !canInteract" placeholder="例如：核对需求与风险" />
          <text class="lp-label">这一阶段具体做什么？</text><textarea v-model="phaseDraft.question" :maxlength="-1" class="lp-field" auto-height :disabled="busy || !canInteract" />
          <text class="lp-label">本阶段验收标准 · 每行一条</text><textarea v-model="phaseDraft.criteria" :maxlength="-1" class="lp-field" auto-height :disabled="busy || !canInteract" />
          <view class="lp-actions"><button role="button" tabindex="0" :class="phaseDraft.input_kind==='documents'?'lp-primary':'lp-secondary'" :disabled="busy || !canInteract" @tap="phaseDraft.input_kind='documents'">资料任务</button><button role="button" tabindex="0" :class="phaseDraft.input_kind==='personal'?'lp-primary':'lp-secondary'" :disabled="busy || !canInteract" @tap="phaseDraft.input_kind='personal'">个人任务 · 无需文件</button></view>
          <text class="lp-note">{{ phaseDraft.input_kind==='personal'?'先只使用这条指令，不自动选入记忆。保存后可在任务计划中明确选择最多8条确认记忆。':'默认使用当前项目资料；保存后可在任务计划中限定文件范围。不会自动继承父阶段的范围。' }}</text>
          <text class="lp-label">引用已有阶段 · 可不选，合计最多 6 个步骤</text><text class="lp-note">手动选择确切报告版本中的步骤；引用的是历史生成成果，不会把它当成新事实或给旧资料重新授权。</text>
          <view v-for="phase in phases.filter(item=>item.report_version!==null)" :key="phase.id" class="lp-parent"><text class="lp-title">{{ phase.title }} · 报告 v{{ phase.report_version }} · {{ reviewLabel(phase.review_status) }}</text><checkbox-group @change="selectParent(phase,$event)"><label v-for="step in phase.analysis_steps" :key="step.id" class="lp-option"><checkbox :value="step.id" :checked="Boolean(selectedParents[phase.id]?.step_ids.includes(step.id))" :disabled="busy || !canInteract || step.status!=='completed'" color="#25493e" /><text>{{ step.title || step.id }} · {{ taskStateLabel(step.status) }}</text></label></checkbox-group></view>
          <text v-if="Object.keys(selectedParents).length" class="lp-note">{{ parentSummary }}</text><button role="button" tabindex="0" class="lp-primary" :disabled="busy || !canInteract || uncertain" @tap="savePhase">保存阶段，不执行</button>
        </view>
        <view v-for="phase in phases" :key="phase.id" class="lp-phase">
          <text class="lp-title">{{ String(phase.ordinal).padStart(2,'0') }} · {{ phase.title }}</text><text class="lp-note">{{ taskStateLabel(phase.task_status) }} · {{ reviewLabel(phase.review_status) }}{{ phase.report_version!==null ? ` · 报告 v${phase.report_version}` : '' }}</text>
          <text v-for="(criterion,index) in phase.acceptance_criteria" :key="index" class="lp-criterion">{{ criterion }}</text>
          <text v-if="phase.parent_refs.length" class="lp-note">{{ handoffLabel(phase) }}</text>
          <view class="lp-actions"><button role="button" tabindex="0" class="lp-secondary" :disabled="busy || !canInteract" @tap="openPhaseTask(phase)">打开本阶段任务计划</button><button v-if="phase.report_version!==null" role="button" tabindex="0" class="lp-secondary" :disabled="busy || !canInteract" @tap="readReport(phase)">读取报告 v{{ phase.report_version }}，准备验收</button></view>
        </view>
        <text v-if="!phases.length" class="lp-note">还没有阶段。可以先建一小步，之后再继续追加；不预先编造未来成果。</text><button v-if="phaseCursor" role="button" tabindex="0" class="lp-secondary" :disabled="busy || !canInteract" @tap="morePhases">读取下一页阶段</button>
        <view v-if="report" class="lp-report"><text class="lp-heading">{{ reportTitle }} · 报告 v{{ report.version }}</text><text class="lp-note">待用户验收；接受只代表你接受这个版本，不表示事实或现实目标已由系统验证。</text><text v-if="!report.available" class="lp-error">来源或成果已不可用，旧正文已收起，不能验收。</text><template v-else><AnswerBody :text="report.content" /><view class="lp-actions"><button role="button" tabindex="0" class="lp-primary" :disabled="busy || !canInteract || uncertain" @tap="reviewReport('accepted')">接受这一版</button><button role="button" tabindex="0" class="lp-secondary" :disabled="busy || !canInteract || uncertain" @tap="reviewReport('rejected')">退回这一版</button></view></template></view>
      </view>
    </view>
  <!-- #ifndef H5 -->
  </view>
  <!-- #endif -->
  <!-- #ifdef H5 -->
  </div>
  <!-- #endif -->
</template>

<script setup>
import {computed,ref,watch,onBeforeUnmount} from 'vue';
import {onHide,onUnload} from '@dcloudio/uni-app';
import {createLongProjectsClient,projectCriteria} from '../services/long-projects.js';
import {createQueryRequestIdAsync,researchConnectionKey} from '../services/api.js';
import {taskStateLabel} from '../services/project-tasks.js';
import AnswerBody from './AnswerBody.vue';
const props=defineProps({sessionId:{type:String,default:''},identity:{type:String,default:''},active:{type:Boolean,default:false},demo:{type:Boolean,default:false},disabled:{type:Boolean,default:false}});
const emit=defineEmits(['busy','dirty','open-task']),client=createLongProjectsClient();
const freshProject=()=>({goal:'',criteria:''}),freshPhase=()=>({title:'',question:'',criteria:'',input_kind:'documents'});
const opened=ref(false),enabled=ref(false),loaded=ref(false),busy=ref(false),error=ref(''),notice=ref(''),uncertain=ref(false);
const projects=ref([]),projectCursor=ref(null),project=ref(null),phases=ref([]),phaseCursor=ref(null),report=ref(null),projectEditor=ref(false),phaseEditor=ref(false);
const draft=ref(freshProject()),phaseDraft=ref(freshPhase()),selectedParents=ref({});
let generation=0;
const canInteract=computed(()=>props.active && !props.demo && !props.disabled && Boolean(props.sessionId) && props.identity===researchConnectionKey());
const dirty=computed(()=>Boolean(draft.value.goal || draft.value.criteria || phaseDraft.value.title || phaseDraft.value.question || phaseDraft.value.criteria || Object.keys(selectedParents.value).length));
const reportTitle=computed(()=>phases.value.find(item=>item.id===report.value?.phase_id)?.title || '阶段成果');
const parentSummary=computed(()=>Object.values(selectedParents.value).map(ref=>`报告 v${ref.report_version}：${ref.step_ids.join('、')}`).join('；'));
const projectStatus=value=>({active:'进行中',accepted:'用户已确认',rejected:'用户已退回'}[value] || '待核对');
const reviewLabel=value=>({not_reviewed:'待你验收',accepted:'用户已接受这一版',rejected:'用户已退回这一版',stale:'旧验收已失效'}[value] || '待核对');
function handoffLabel(phase){return phase.handoff_status==='references_only_not_delivered'?'已登记父阶段引用；尚未证明已传入模型，不冒充完成交接。':'父阶段引用的实际交接状态需核对服务回执，不从阶段完成推断。';}
function setBusy(value){busy.value=value;emit('busy',value);}
function activateButton(event){if(!canInteract.value || busy.value || !event || event.repeat || event.isComposing || event.ctrlKey || event.metaKey || event.shiftKey || event.altKey || !['Enter',' ','Spacebar'].includes(event.key))return;const button=event.target?.closest?.('[role="button"]');if(!button || button.hasAttribute?.('disabled') || button.getAttribute?.('aria-disabled')==='true' || typeof button.click!=='function')return;event.preventDefault?.();button.click();}
function capture(){const token=++generation,session=props.sessionId,key=props.identity;return {session,current:()=>token===generation && props.active && session===props.sessionId && key===props.identity && key===researchConnectionKey()};}
async function operation(work){if(!canInteract.value || busy.value)return;const ctx=capture();setBusy(true);error.value='';notice.value='';try{await work(ctx);}catch(issue){if(ctx.current())error.value=issue?.status===409?'项目、阶段或报告版本已改变。请读取最新状态；草稿保留，不自动覆盖或重发。':issue?.message || '操作未确认，请手动读取状态。';}finally{if(ctx.current())setBusy(false);}}
const confirm=(title,content)=>new Promise(resolve=>uni.showModal({title,content,confirmText:'确认',cancelText:'先不继续',success:value=>resolve(value?.confirm===true),fail:()=>resolve(false)}));
const criteria=value=>projectCriteria(value.split('\n').map(item=>item.trim()).filter(Boolean));
function hide(){generation++;opened.value=false;loaded.value=false;enabled.value=false;projects.value=[];project.value=null;phases.value=[];report.value=null;projectCursor.value=null;phaseCursor.value=null;error.value='';notice.value='';setBusy(false);}
function reset(){hide();draft.value=freshProject();phaseDraft.value=freshPhase();selectedParents.value={};projectEditor.value=false;phaseEditor.value=false;uncertain.value=false;}
watch(()=>[props.sessionId,props.identity],reset);watch(()=>props.active,value=>{if(!value)hide();});watch(dirty,value=>emit('dirty',value));
async function toggle(){if(!canInteract.value || busy.value)return;if(opened.value){hide();return;}opened.value=true;await refresh();}
async function refresh(){await operation(async ctx=>{report.value=null;const value=await client.load(ctx.session,{isCurrent:ctx.current});if(!ctx.current())return;loaded.value=true;enabled.value=value.enabled;projects.value=value.items;projectCursor.value=value.next_cursor;project.value=null;phases.value=[];notice.value='已读取项目，没有调用模型。';});}
async function moreProjects(){if(!projectCursor.value)return;await operation(async ctx=>{const after=projectCursor.value,value=await client.load(ctx.session,{cursor:after,isCurrent:ctx.current});if(!ctx.current())return;const ids=new Set(projects.value.map(item=>item.id));projects.value.push(...value.items.filter(item=>!ids.has(item.id)));projectCursor.value=value.next_cursor===after?null:value.next_cursor;});}
async function openProject(projectId){if(!canInteract.value || busy.value)return;const gate=capture();if(phaseEditor.value && dirty.value && !(await confirm('切换长期项目？','新阶段草稿会被清空，不会带入另一个长期项目。')))return;if(!gate.current())return;await operation(async ctx=>{report.value=null;const current=await client.detail(ctx.session,projectId,{isCurrent:ctx.current}),page=await client.phases(ctx.session,projectId,{isCurrent:ctx.current});if(!ctx.current())return;project.value=current;phases.value=page.items;phaseCursor.value=page.next_cursor;phaseDraft.value=freshPhase();selectedParents.value={};phaseEditor.value=false;});}
async function refreshPhases(){if(project.value)await openProject(project.value.id);}
async function morePhases(){if(!project.value || !phaseCursor.value)return;await operation(async ctx=>{const after=phaseCursor.value,value=await client.phases(ctx.session,project.value.id,{cursor:after,isCurrent:ctx.current});if(!ctx.current())return;const ids=new Set(phases.value.map(item=>item.id));phases.value.push(...value.items.filter(item=>!ids.has(item.id)));phaseCursor.value=value.next_cursor===after?null:value.next_cursor;});}
async function startProject(){if(!canInteract.value || busy.value || !enabled.value)return;const ctx=capture();if((dirty.value || uncertain.value) && !(await confirm('新建另一份目标？','未保存草稿会清空；上次结果未明的操作可能已保存，请先核对列表。这是准备另一份草稿，不会重发旧请求。')))return;if(!ctx.current())return;draft.value=freshProject();phaseDraft.value=freshPhase();selectedParents.value={};projectEditor.value=true;phaseEditor.value=false;uncertain.value=false;}
async function saveProject(){if(uncertain.value)return;await operation(async ctx=>{const acceptance_criteria=criteria(draft.value.criteria),request_id=await createQueryRequestIdAsync({isCurrent:ctx.current});if(!ctx.current())return;let value;try{value=await client.create(ctx.session,{request_id,goal:draft.value.goal,acceptance_criteria},{isCurrent:ctx.current});}catch(issue){if(ctx.current() && issue?.submission_uncertain)uncertain.value=true;throw issue;}if(!ctx.current())return;project.value=value;projects.value=[value,...projects.value.filter(item=>item.id!==value.id)];phases.value=[];phaseCursor.value=null;draft.value=freshProject();projectEditor.value=false;notice.value='目标与验收标准已保存。尚未创建执行批次。';});}
async function startPhase(){if(!canInteract.value || busy.value || !project.value)return;const ctx=capture();if(((phaseEditor.value && dirty.value) || uncertain.value) && !(await confirm('新建另一阶段草稿？','当前阶段草稿会清空；上次结果未明的操作可能已保存，请先核对阶段列表。这不会重发旧请求。')))return;if(!ctx.current())return;phaseDraft.value=freshPhase();selectedParents.value={};phaseEditor.value=true;report.value=null;uncertain.value=false;}
function selectParent(phase,event){if(!canInteract.value || busy.value || !phaseEditor.value)return;const values=event?.detail?.value;if(!Array.isArray(values) || new Set(values).size!==values.length || phase.report_version===null || values.some(value=>!phase.analysis_steps.some(step=>step.id===value && step.status==='completed')))return;const next={...selectedParents.value};if(values.length)next[phase.id]={phase_id:phase.id,report_version:phase.report_version,step_ids:[...values]};else delete next[phase.id];if(Object.values(next).reduce((sum,item)=>sum+item.step_ids.length,0)>6){error.value='父阶段合计最多选择6个步骤，没有扩大输入。';return;}selectedParents.value=next;}
function checkedParents(){return Object.values(selectedParents.value).map(ref=>{const phase=phases.value.find(item=>item.id===ref.phase_id);if(!phase || phase.report_version!==ref.report_version || ref.step_ids.some(id=>!phase.analysis_steps.some(step=>step.id===id && step.status==='completed')))throw new Error('所选父阶段版本或步骤已变化，请重新核对，不会自动改用新版。');return {...ref,step_ids:[...ref.step_ids]};});}
async function savePhase(){if(!project.value || uncertain.value)return;await operation(async ctx=>{const current=project.value,acceptance_criteria=criteria(phaseDraft.value.criteria),parent_refs=checkedParents(),question={id:'q1',title:phaseDraft.value.title,question:phaseDraft.value.question,...(phaseDraft.value.input_kind==='personal'?{input_kind:'personal',memory_ids:[]}: {})},request_id=await createQueryRequestIdAsync({isCurrent:ctx.current});if(!ctx.current())return;let result;try{result=await client.createPhase(ctx.session,current.id,{request_id,expected_revision:current.revision,title:phaseDraft.value.title,acceptance_criteria,questions:[question],parent_refs},{isCurrent:ctx.current});}catch(issue){if(ctx.current() && issue?.submission_uncertain)uncertain.value=true;throw issue;}if(!ctx.current())return;project.value=result.project;phases.value=[...phases.value,result.phase];phaseDraft.value=freshPhase();selectedParents.value={};phaseEditor.value=false;notice.value='阶段已保存，没有调用模型。打开本阶段任务，核对输入和步骤后再批准额度。';});}
function openPhaseTask(phase){if(canInteract.value && !busy.value && phases.value.some(item=>item.id===phase.id))emit('open-task',phase.task_id);}
async function readReport(phase){await operation(async ctx=>{report.value=null;const value=await client.report(ctx.session,phase,{isCurrent:ctx.current});if(ctx.current())report.value=value;});}
async function reviewReport(decision){if(!project.value || !report.value?.available || uncertain.value)return;await operation(async ctx=>{const phase=phases.value.find(item=>item.id===report.value.phase_id),current=project.value;if(!phase || phase.report_version!==report.value.version)throw new Error('报告版本已变化，请重新读取。');report.value=null;const checked=await client.report(ctx.session,phase,{isCurrent:ctx.current});if(!ctx.current())return;report.value=checked;if(!checked.available)return;if(!(await confirm(decision==='accepted'?'接受这一版阶段成果？':'退回这一版阶段成果？',`只记录你对报告 v${checked.version} 的判断，不证明事实或总目标已经验证，不执行下一阶段。`)) || !ctx.current())return;const request_id=await createQueryRequestIdAsync({isCurrent:ctx.current});if(!ctx.current())return;let result;try{result=await client.review(ctx.session,current.id,phase.id,{expected_revision:current.revision,request_id,report_version:checked.version,decision},{isCurrent:ctx.current});}catch(issue){if(ctx.current() && issue?.submission_uncertain)uncertain.value=true;throw issue;}if(!ctx.current())return;project.value=result.project;phases.value=phases.value.map(item=>item.id===phase.id?result.phase:item);report.value=null;notice.value=decision==='accepted'?'已记录你接受这一版；没有自动执行下一阶段。':'已记录退回这一版；没有自动重跑。';});}
onHide(hide);onUnload(reset);onBeforeUnmount(reset);
</script>

<style scoped>
.long-projects{margin:0 0 16px;border:1px solid #dde3d5;border-radius:14px;background:#fbfcf7;color:#304a3b;overflow:hidden}.lp-disclosure{display:flex;align-items:center;justify-content:space-between;width:100%;margin:0;padding:13px 17px;background:transparent;text-align:left;min-height:52px}.lp-panel{padding:0 17px 20px}.lp-title,.lp-heading,.lp-label,.lp-note,.lp-error,.lp-criterion{display:block;overflow-wrap:anywhere;line-height:1.8}.lp-title{font-size:13px;font-weight:650}.lp-heading{font-size:16px;font-weight:650;margin-top:14px}.lp-note{font-size:11px;color:#73816c;margin:6px 0}.lp-label{font-size:12px;font-weight:600;margin:12px 0 6px}.lp-criterion{font-size:12px;margin:5px 0}.lp-error{font-size:12px;color:#916239;margin:8px 0}.lp-actions{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin:10px 0}.lp-primary,.lp-secondary{min-height:44px;margin:0;padding:9px 13px;border-radius:10px;font-size:12px;line-height:1.7;background:#25493e;color:#fff}.lp-secondary{background:#eef2e6;border:1px solid #dce3cf;color:#41543a}.lp-field{box-sizing:border-box;width:100%;min-height:54px;padding:11px;border:1px solid #e0e5d8;border-radius:9px;background:#fafbf6;font-size:13px;line-height:1.9;color:#34432f}.lp-editor,.lp-report{padding:14px;margin-top:14px;border:1px solid #dce5d2;border-radius:12px;background:#fff}.lp-row{display:block;width:100%;margin:8px 0;padding:12px;text-align:left;background:#f5f7ef;border-radius:11px}.lp-phase,.lp-parent{padding:13px 0;border-top:1px solid #e0e6d8;margin-top:12px}.lp-option{display:flex;align-items:center;gap:8px;min-height:44px;font-size:12px}.long-projects button::after{border:0}.long-projects button[disabled]{opacity:.45}@media(max-width:680px){.lp-panel{padding:0 12px 16px}.lp-editor,.lp-report{padding:11px}.lp-actions{align-items:stretch}.lp-primary,.lp-secondary{white-space:normal}}
</style>
